(()=>{'use strict';document.addEventListener('DOMContentLoaded',()=>{const hans=new URLSearchParams(location.search).get('lang')==='zh-Hans'||location.hostname==='cn.globalprotectionwall.com';const href=hans?'https://cn.globalprotectionwall.com/child-advocacy-site/zh-Hans/features/social-observation/adoption-social-work-child-safety-20260918/':'https://jerryzuhow77.github.io/child-advocacy-site/features/social-observation/adoption-social-work-child-safety-20260918/';const t=hans?{k:'多元观察 · 09.18',h:'收出养社工与儿童安全：把角色边界放回孩子身上',p:'从分工、风险升级到跨系统交接：每一个警讯，谁负责接住？',a:'阅读专题 →'}:{k:'多元觀察 · 09.18',h:'收出養社工與兒少安全：把角色界線放回孩子身上',p:'從分工、風險升級到跨系統交接：每一個警訊，誰負責接住？',a:'閱讀專題 →'};const style=document.createElement('style');style.textContent='.home-adoption-card{display:block;margin:14px 0;padding:20px 22px;border-radius:18px;background:linear-gradient(135deg,#fff9ef,#e7f0e9);border:1px solid rgba(54,122,108,.25);color:#253d42;text-decoration:none;box-shadow:0 8px 22px rgba(42,78,66,.1)}.home-adoption-card small{display:block;color:#367a6c;font-weight:800;letter-spacing:.06em}.home-adoption-card strong{display:block;margin:5px 0;font-size:1.18rem;line-height:1.45}.home-adoption-card span{display:block;line-height:1.65}.home-adoption-card em{display:block;margin-top:10px;color:#a74937;font-style:normal;font-weight:800}';document.head.append(style);const card=()=>{const a=document.createElement('a');a.className='home-adoption-card';a.href=href;a.innerHTML='<small>'+t.k+'</small><strong>'+t.h+'</strong><span>'+t.p+'</span><em>'+t.a+'</em>';return a};const pinned=document.querySelector('.home-pinned-reports-grid,.home-pinned-grid,[data-pinned-reports]');if(pinned&&!pinned.querySelector('.home-adoption-card'))pinned.prepend(card());const feature=document.querySelector('#multiple-perspectives,.special-feature-nav-menu,[data-special-feature-menu]');if(feature&&!feature.querySelector('.home-adoption-card'))feature.append(card());});})();